layer.css:
[data-ryt="pitch"] { color: rgb(68, 68, 68); background-color: rgb(204, 204, 204); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: italic; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(68, 68, 68); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 30px; padding-right: 30px; padding-bottom: 30px; padding-left: 30px; transition: all }
[data-ryt="footer"] { color: var(--ryt-text); background-color: rgb(112, 128, 144); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.3s }
[data-ryt="brand"] { color: rgb(255, 71, 15); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 32px; font-weight: 700; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(255, 71, 15); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.3s }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18.72px; font-weight: 700; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="review"] { color: rgb(121, 121, 121); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(121, 121, 121); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.3s }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18.72px; font-weight: 700; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { opacity: 0.6; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="brand"]:hover { opacity: 0.6; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { opacity: 0.6; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
